### 📄 `FileBrowserMorph.js`

```javascript
import { Morph, Label, Button, Text, List, HorizontalLayout, VerticalLayout } from 'lively.morphic';
import { Color } from 'lively.graphics';
import { resource } from 'lively.resources';

export class FileBrowserMorph extends Morph {
  constructor({ startPath = '', onSave = () => {}, onClose = () => {} } = {}) {
    super({
      layout: new VerticalLayout({ spacing: 5 }),
      extent: pt(400, 500),
      fill: Color.white,
      borderColor: Color.gray,
      borderWidth: 1,
      name: 'file browser'
    });

    this.history = [];
    this.currentPath = startPath || '';
    this.onSave = onSave;
    this.onClose = onClose;
    this.selectedFile = '';

    this.buildUI();
    this.loadDirectory(this.currentPath);
  }

  buildUI() {
    // Top button row
    const buttonRow = new Morph({
      layout: new HorizontalLayout({ spacing: 5 }),
      extent: pt(400, 30),
      submorphs: [
        this.makeButton('⬅ Back', () => this.goBack()),
        this.makeButton('⬆ Up', () => this.goUp()),
        this.makeButton('💾 Save', () => this.saveSelection()),
        this.makeButton('✖ Close', () => this.onClose())
      ]
    });

    // File list
    this.fileList = new List({
      name: 'file list',
      extent: pt(400, 400),
      items: [],
      selectOnClick: true,
      onItemClick: (item) => this.handleClick(item)
    });

    // Filename display
    this.filenameBox = new Text({
      extent: pt(400, 30),
      fixedHeight: true,
      readOnly: true,
      textAndAttributes: ['']
    });

    this.addMorph(buttonRow);
    this.addMorph(this.fileList);
    this.addMorph(this.filenameBox);
  }

  makeButton(label, action) {
    return new Button({
      label,
      extent: pt(90, 30),
      onClick: action
    });
  }

  async loadDirectory(path) {
    try {
      const response = await fetch(`/api/contents/${path}`);
      const json = await response.json();

      if (this.currentPath) this.history.push(this.currentPath);
      this.currentPath = json.path;

      this.fileList.items = json.content.map(item => ({
        label: item.name + (item.type === 'directory' ? '/' : ''),
        isDir: item.type === 'directory',
        path: item.path
      }));

      this.filenameBox.textString = '';
      this.selectedFile = '';
    } catch (err) {
      this.fileList.items = [{ label: '(error loading directory)' }];
      console.error(err);
    }
  }

  handleClick(item) {
    if (item.isDir) {
      this.loadDirectory(item.path);
    } else {
      this.selectedFile = item.path;
      this.filenameBox.textString = item.label;
    }
  }

  goBack() {
    if (this.history.length > 0) {
      const prev = this.history.pop();
      this.loadDirectory(prev);
    }
  }

  goUp() {
    const parts = this.currentPath.split('/');
    if (parts.length > 1) {
      parts.pop();
      this.loadDirectory(parts.join('/'));
    } else {
      this.loadDirectory('');
    }
  }

  saveSelection() {
    if (this.selectedFile) {
      this.onSave(this.selectedFile);
    }
  }
}
```

