#### 2. `JupyterFileSystem.js`
Implements `FileSystem` using Jupyter’s `/api/contents/`:

```js
import { FileSystem } from './FileSystem.js';

export class JupyterFileSystem extends FileSystem {
  constructor(startPath = '') {
    super();
    this.currentPath = startPath;
    this.history = [];
  }

  async list(path) {
    const response = await fetch(`/api/contents/${path}`);
    const json = await response.json();

    if (this.currentPath) this.history.push(this.currentPath);
    this.currentPath = json.path;

    return json.content.map(item => ({
      label: item.name + (item.type === 'directory' ? '/' : ''),
      isDir: item.type === 'directory',
      path: item.path
    }));
  }

  async goUp() {
    const parts = this.currentPath.split('/');
    if (parts.length > 1) {
      parts.pop();
      return this.list(parts.join('/'));
    } else {
      return this.list('');
    }
  }

  async goBack() {
    if (this.history.length > 0) {
      const prev = this.history.pop();
      return this.list(prev);
    }
    return [];
  }

  getCurrentPath() {
    return this.currentPath;
  }
}
```

