### 🧪 `JupyterFileSystem` Implementation

```js
import { FileSystem } from './FileSystem.js';

export class JupyterFileSystem extends FileSystem {
  constructor(startPath = '') {
    super();
    this._currentPath = startPath;
    this.history = [];
  }

  get currentPath() {
    return this._currentPath;
  }

  set currentPath(val) {
    this._currentPath = val;
  }

  async list(path) {
    const response = await fetch(`/api/contents/${path}`);
    const json = await response.json();

    if (this._currentPath) this.history.push(this._currentPath);
    this._currentPath = json.path;

    return json.content.map(item => ({
      label: item.name + (item.type === 'directory' ? '/' : ''),
      isDir: item.type === 'directory',
      path: item.path
    }));
  }

  async goUp() {
    const parts = this._currentPath.split('/');
    if (parts.length > 1) {
      parts.pop();
      return this.list(parts.join('/'));
    } else {
      return this.list('');
    }
  }

  async goBack() {
    if (this.history.length > 0) {
      const prev = this.history.pop();
      return this.list(prev);
    }
    return [];
  }

  async open(path) {
    const response = await fetch(`/api/contents/${path}`);
    const json = await response.json();
    return json;
  }

  async save(path, data) {
    const response = await fetch(`/api/contents/${path}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
    const json = await response.json();
    return json;
  }
}
```

